package cn.sixnine.filmlog;

import android.app.Activity;
import android.graphics.*;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import java.io.File;
import java.util.*;
import java.util.concurrent.*;

public final class ScanViewerActivity extends WorkspaceActivity {
    private Button singleClose;private boolean single;private Bitmap bitmap;private ZoomImage image;private TextView counter;private Button previous,next;
    private final ArrayList<String> order=new ArrayList<>();private int position;private volatile int generation;
    private final ExecutorService worker=Executors.newSingleThreadExecutor();private final android.os.Handler main=new android.os.Handler(android.os.Looper.getMainLooper());
    private int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
    private Button control(String label,Runnable action){Button button=UiSpacing.button(this);button.setText(label);button.setAllCaps(false);button.setTextSize(14);button.setTextColor(0xffef8249);button.setBackgroundColor(Color.BLACK);button.setMinWidth(0);button.setMinimumWidth(0);button.setMinHeight(dp(48));button.setOnClickListener(v->action.run());return button;}
    @Override public void onCreate(Bundle state){super.onCreate(state);single=getIntent().getBooleanExtra("single",false);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(Color.BLACK);setContentView(root);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),single?0:i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());if(singleClose!=null){FrameLayout.LayoutParams p=(FrameLayout.LayoutParams)singleClose.getLayoutParams();p.topMargin=i.getSystemWindowInsetTop()+dp(12);singleClose.setLayoutParams(p);}return i;});root.requestApplyInsets();
        View header=LibraryUi.header(this,"",this::finish,LibraryUi.icon(this,0xe036,"重试",()->load(position)));counter=header.findViewWithTag("library-header-title");counter.setTextColor(0xfff4eee2);counter.setTextSize(14);((TextView)((ViewGroup)header).getChildAt(1)).setTextColor(0xfff4eee2);((TextView)((ViewGroup)header).getChildAt(2)).setTextColor(0xfff4eee2);if(single)header.setVisibility(View.GONE);root.addView(header);
        image=new ZoomImage();root.addView(image,new LinearLayout.LayoutParams(-1,0,1));LinearLayout navigation=new LinearLayout(this);previous=control("‹ 上一张",()->load(position-1));next=control("下一张 ›",()->load(position+1));navigation.addView(previous,new LinearLayout.LayoutParams(0,-2,1));navigation.addView(next,new LinearLayout.LayoutParams(0,-2,1));root.addView(navigation);TextView hint=new TextView(this);hint.setText("双击/双指缩放 · 放大后拖动 · 原比例左右滑动翻页");hint.setTextColor(0xffb4a99f);hint.setTextSize(12);hint.setGravity(Gravity.CENTER);hint.setPadding(dp(12),dp(4),dp(12),dp(8));root.addView(hint);if(single){navigation.setVisibility(View.GONE);hint.setVisibility(View.GONE);root.removeView(image);FrameLayout full=new FrameLayout(this);full.addView(image,new FrameLayout.LayoutParams(-1,-1));singleClose=control(String.valueOf((char)0xe4f6),()->finish());singleClose.setTypeface(android.graphics.Typeface.createFromAsset(getAssets(),"fonts/Phosphor.ttf"));singleClose.setTextSize(android.util.TypedValue.COMPLEX_UNIT_DIP,24);singleClose.setTextColor(Color.WHITE);singleClose.setPadding(0,0,0,0);singleClose.setStateListAnimator(null);singleClose.setContentDescription("关闭照片");android.graphics.drawable.GradientDrawable background=new android.graphics.drawable.GradientDrawable();background.setColor(0x80000000);background.setCornerRadius(dp(22));singleClose.setBackground(background);FrameLayout.LayoutParams closeSize=new FrameLayout.LayoutParams(dp(44),dp(44),Gravity.TOP|Gravity.RIGHT);closeSize.setMargins(0,dp(12),dp(16),0);full.addView(singleClose,closeSize);root.addView(full,new LinearLayout.LayoutParams(-1,0,1));root.requestApplyInsets();image.setContentDescription("照片，可双指缩放并拖动，点按关闭");}
        String reference=getIntent().getStringExtra("reference");if(reference!=null){order.add(reference);image.setContentDescription(single?"参考照片，可双指缩放并拖动，点按关闭":"参考照片，可双击或双指缩放并拖动");load(0);return;}String roll=getIntent().getStringExtra("viewer_roll");if(roll!=null&&!single)try(LogStore logs=new LogStore(this)){String previewRoll=getIntent().getStringExtra("preview_roll");ArrayList<ScanStore.Scan> scans=previewRoll!=null&&!previewRoll.isEmpty()?ImportQueue.previews(logs,roll):new ScanStore(this,logs).list(roll,getIntent().getBooleanExtra("trash",false));if(getIntent().getBooleanExtra("by_name",false))scans.sort(Comparator.comparing((ScanStore.Scan scan)->scan.name,String.CASE_INSENSITIVE_ORDER).thenComparing(scan->scan.id));if(getIntent().getBooleanExtra("by_frame",false)){Map<String,Integer> frames=new HashMap<>();for(LogStore.Shot shot:logs.shots(roll))frames.put(shot.id,shot.frame);scans.removeIf(scan->scan.shotId.isEmpty());scans.sort(Comparator.comparingInt(scan->frames.getOrDefault(scan.shotId,Integer.MAX_VALUE)));}for(ScanStore.Scan scan:scans)order.add(scan.id);}catch(Exception unavailable){Toast.makeText(this,"无法载入整卷顺序，仅打开当前扫描",1).show();}String current=state==null?getIntent().getStringExtra("scan"):state.getString("current",getIntent().getStringExtra("scan"));if(current!=null&&!order.contains(current))order.add(current);if(order.isEmpty()){Toast.makeText(this,"没有可查看的扫描",1).show();finish();return;}load(Math.max(0,order.indexOf(current)));
    }
    private void load(int index){if(index<0||index>=order.size())return;position=index;final int request=++generation;final String id=order.get(index);previous.setEnabled(index>0);next.setEnabled(index+1<order.size());previous.setAlpha(index>0?1:.35f);next.setAlpha(index+1<order.size()?1:.35f);counter.setText((index+1)+" / "+order.size()+" · 正在加载");image.setImageDrawable(null);if(bitmap!=null){bitmap.recycle();bitmap=null;}
        worker.execute(()->{if(request!=generation)return;Bitmap loaded=null;String error=null;try(LogStore logs=new LogStore(getBaseContext())){String previewRoll=getIntent().getStringExtra("preview_roll");if(previewRoll!=null&&!previewRoll.isEmpty())loaded=ScanImages.read(getApplicationContext(),ImportQueue.previewUri(logs,previewRoll,id),2560);else if(getIntent().hasExtra("reference"))loaded=ScanImages.read(ReferencePhotos.file(getBaseContext(),logs,id),2560);else loaded=ScanImages.read(new ScanStore(getApplicationContext(),logs).file(id),2560);}catch(Exception problem){error=problem.getMessage();}final Bitmap ready=loaded;final String problem=error;main.post(()->{if(isDestroyed()||request!=generation){if(ready!=null)ready.recycle();return;}bitmap=ready;counter.setText((getIntent().hasExtra("reference")?"参考照片 · ":"")+(position+1)+" / "+order.size()+(ready==null?" · 无法读取":""));if(ready!=null){image.setImageBitmap(ready);image.post(()->image.fit());}else Toast.makeText(this,"无法打开扫描："+problem,1).show();});});
    }
    @Override protected void onSaveInstanceState(Bundle state){if(!order.isEmpty())state.putString("current",order.get(position));super.onSaveInstanceState(state);}
    private final class ZoomImage extends ImageView {
        private final Matrix transform=new Matrix();private float base=1,scale=1,x,y;private boolean multiTouch;private final ScaleGestureDetector pinch;private final GestureDetector taps;
        ZoomImage(){super(ScanViewerActivity.this);setScaleType(ScaleType.MATRIX);setFocusable(true);setContentDescription("扫描照片，可双击或双指缩放并拖动");taps=new GestureDetector(ScanViewerActivity.this,new GestureDetector.SimpleOnGestureListener(){@Override public boolean onDown(MotionEvent e){return true;}@Override public boolean onFling(MotionEvent start,MotionEvent end,float vx,float vy){if(single||start==null||end==null||multiTouch||scale>base*1.1f)return false;float dx=end.getX()-start.getX(),dy=end.getY()-start.getY();if(Math.abs(dx)<dp(60)||Math.abs(dx)<Math.abs(dy)*1.5f)return false;load(position+(dx<0?1:-1));return true;}@Override public boolean onSingleTapConfirmed(MotionEvent e){if(single&&!multiTouch){finish();return true;}return false;}@Override public boolean onDoubleTap(MotionEvent e){if(single)return false;if(scale>base*1.1f)fit();else{transform.postScale(3,3,e.getX(),e.getY());scale=base*3;constrain();}return true;}});pinch=new ScaleGestureDetector(ScanViewerActivity.this,new ScaleGestureDetector.SimpleOnScaleGestureListener(){@Override public boolean onScale(ScaleGestureDetector detector){float next=Math.max(base,Math.min(base*8,scale*detector.getScaleFactor()));transform.postScale(next/scale,next/scale,detector.getFocusX(),detector.getFocusY());scale=next;constrain();return true;}});}
        private void zoom(float ratio){if(bitmap==null)return;float next=Math.max(base,Math.min(base*8,base*ratio));transform.postScale(next/scale,next/scale,getWidth()/2f,getHeight()/2f);scale=next;constrain();announceForAccessibility("缩放 "+Math.round(scale/base*10)/10f+" 倍");}
        @Override public void onInitializeAccessibilityNodeInfo(android.view.accessibility.AccessibilityNodeInfo info){super.onInitializeAccessibilityNodeInfo(info);info.addAction(new android.view.accessibility.AccessibilityNodeInfo.AccessibilityAction(R.id.zoom_in,"放大照片"));info.addAction(new android.view.accessibility.AccessibilityNodeInfo.AccessibilityAction(R.id.zoom_out,"缩小照片"));info.addAction(new android.view.accessibility.AccessibilityNodeInfo.AccessibilityAction(R.id.zoom_reset,"恢复整张照片"));}
        @Override public boolean performAccessibilityAction(int action,Bundle args){if(action==R.id.zoom_in){zoom(scale/base*2);return true;}if(action==R.id.zoom_out){zoom(scale/base/2);return true;}if(action==R.id.zoom_reset){fit();announceForAccessibility("已恢复整张照片");return true;}return super.performAccessibilityAction(action,args);}
        @Override public boolean onKeyDown(int key,KeyEvent event){if(key==KeyEvent.KEYCODE_PLUS||key==KeyEvent.KEYCODE_EQUALS||key==KeyEvent.KEYCODE_NUMPAD_ADD){zoom(scale/base*2);return true;}if(key==KeyEvent.KEYCODE_MINUS||key==KeyEvent.KEYCODE_NUMPAD_SUBTRACT){zoom(scale/base/2);return true;}if(key==KeyEvent.KEYCODE_0||key==KeyEvent.KEYCODE_NUMPAD_0){fit();return true;}
            if(key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT||key==KeyEvent.KEYCODE_DPAD_UP||key==KeyEvent.KEYCODE_DPAD_DOWN){if(scale>base*1.1f){transform.postTranslate(key==KeyEvent.KEYCODE_DPAD_LEFT?dp(48):key==KeyEvent.KEYCODE_DPAD_RIGHT?-dp(48):0,key==KeyEvent.KEYCODE_DPAD_UP?dp(48):key==KeyEvent.KEYCODE_DPAD_DOWN?-dp(48):0);constrain();return true;}if(!single&&(key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT)){load(position+(key==KeyEvent.KEYCODE_DPAD_LEFT?-1:1));return true;}}return super.onKeyDown(key,event);}
        void fit(){if(bitmap==null||getWidth()==0||getHeight()==0)return;base=Math.min((float)getWidth()/bitmap.getWidth(),(float)getHeight()/bitmap.getHeight());scale=base;transform.setScale(base,base);transform.postTranslate((getWidth()-bitmap.getWidth()*base)/2,(getHeight()-bitmap.getHeight()*base)/2);setImageMatrix(transform);}
        @Override protected void onSizeChanged(int w,int h,int oldW,int oldH){super.onSizeChanged(w,h,oldW,oldH);fit();}
        private void constrain(){if(bitmap==null)return;RectF bounds=new RectF(0,0,bitmap.getWidth(),bitmap.getHeight());transform.mapRect(bounds);float dx=bounds.width()<=getWidth()?(getWidth()-bounds.width())/2-bounds.left:bounds.left>0?-bounds.left:bounds.right<getWidth()?getWidth()-bounds.right:0;float dy=bounds.height()<=getHeight()?(getHeight()-bounds.height())/2-bounds.top:bounds.top>0?-bounds.top:bounds.bottom<getHeight()?getHeight()-bounds.bottom:0;transform.postTranslate(dx,dy);setImageMatrix(transform);}
        @Override public boolean onTouchEvent(MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_DOWN)multiTouch=false;if(e.getPointerCount()>1)multiTouch=true;taps.onTouchEvent(e);pinch.onTouchEvent(e);if(e.getActionMasked()==MotionEvent.ACTION_DOWN){x=e.getX();y=e.getY();}else if(e.getActionMasked()==MotionEvent.ACTION_MOVE&&!pinch.isInProgress()){transform.postTranslate(e.getX()-x,e.getY()-y);constrain();}x=e.getX();y=e.getY();return true;}
    }
    @Override protected void onDestroy(){generation++;worker.shutdownNow();if(image!=null)image.setImageDrawable(null);if(bitmap!=null)bitmap.recycle();super.onDestroy();}
}
